// Returns a pointer to the first element of arr equal to target,
// or NULL if no element is equal to target.
int *find(int *arr, size_t n, int target) {
    for (int *p = arr; p < arr + n; p++) {
        if (*p == target) {
            return p;
        }
    }
    return NULL;
}

int main(void) {
    int arr[] = {4, 8, 15, 16, 23, 42};
    int *p = find(arr, 6, 16);
    if (p != NULL) {
        printf("found %d at index %td\n", *p, p - arr);
    }
    p = find(arr, 6, 5);
    if (p == NULL) {
        printf("5 not found\n");
    }
    return 0;
}

