#include <stdio.h>

// Stores the smallest element of a in *lo and the largest in *hi (n >= 1).
void minmax(int a[], size_t n, int *lo, int *hi) {
    *lo = a[0];
    *hi = a[0];
    for (size_t i = 1; i < n; i++) {
        if (a[i] < *lo) {
            *lo = a[i];
        }
        if (a[i] > *hi) {
            *hi = a[i];
        }
    }
}

int main(void) {
    int a[] = {6, -3, 1, 8, 7};
    int small;
    int big;
    minmax(a, 5, &small, &big);
    printf("min = %d, max = %d\n", small, big);
    return 0;
}

#include <stdio.h>

// arr holds positive values followed by a 0 that marks the end
// (at least one positive value). Returns a pointer to the smallest value.
int *ptr2min(int *arr) {
    int *lo = arr;
    for (int *p = arr + 1; *p != 0; p++) {
        if (*p < *lo) {
            lo = p;
        }
    }
    return lo;
}

int main(void) {
    int a[] = {7, 3, 9, 3, 5, 0};
    int *p = ptr2min(a);
    printf("min = %d at index %td\n", *p, p - a);
    int b[] = {12, 0};
    p = ptr2min(b);
    printf("min = %d at index %td\n", *p, p - b);
    return 0;
}
